# Review package: 5f23262..HEAD

## Commits
edca8a5 test: correct topWords passage comment and pin literal word count

## Files changed
 test/readingTimeMinutes.test.js | 2 ++
 test/topWords.test.js           | 3 ++-
 2 files changed, 4 insertions(+), 1 deletion(-)

## Diff
diff --git a/test/readingTimeMinutes.test.js b/test/readingTimeMinutes.test.js
index 1f0479b..9bbabf3 100644
--- a/test/readingTimeMinutes.test.js
+++ b/test/readingTimeMinutes.test.js
@@ -93,12 +93,14 @@ test('uses the default rate of 200 when wpm is explicitly undefined', () => {
   assert.equal(readingTimeMinutes(words(200), undefined), 1);
 });

 test('validates the text before the rate', () => {
   assertThrowsWithPrefix(() => readingTimeMinutes(42, 0), TypeError);
   assertThrowsWithPrefix(() => readingTimeMinutes(undefined, NaN), TypeError);
 });

 test('counts hyphenated compounds, contractions and decimals like wordCount', () => {
   const text = "A well-known fact: it doesn't cost 3.14 dollars.";
+  assert.equal(wordCount(text), 9);
+  assert.equal(readingTimeMinutes(text, 1), 9);
   assert.equal(readingTimeMinutes(text, 1), wordCount(text));
 });
diff --git a/test/topWords.test.js b/test/topWords.test.js
index 03df28e..a3a3f96 100644
--- a/test/topWords.test.js
+++ b/test/topWords.test.js
@@ -1,15 +1,16 @@
 const { test } = require('node:test');
 const assert = require('node:assert/strict');
 const { topWords } = require('../src/textstats');

-// "keeper" x3, "lamp" x3, "night" x2, "tower" x2, "storm" x1. Stop words
+// "keeper" x3, "lamp" x3, "night" x2, "tower" x2, then several words at x1,
+// of which "climbed" sorts first alphabetically. Stop words
 // (the, a, of, and, on, in, was) are present on purpose and must not appear.
 const PASSAGE = [
   'The keeper lit the lamp. The lamp was old, and the keeper was older.',
   'On a night of storm the tower shook; in the night the keeper climbed',
   'the tower, lamp in hand.',
 ].join(' ');

 const CASES = [
   ["apple", 1, [{"word": "apple", "count": 1}]],
   ["apple apple", 1, [{"word": "apple", "count": 2}]],

